"""Build a portable, dependency-free academic website from shared components.

Run: python3 scripts/build.py
All pages are complete HTML; JavaScript only enhances navigation and filtering.
"""
from pathlib import Path
from html import escape
import json, re

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT/'data/publications.json').read_text())
PAPERS = DATA['publications']
SCHOLAR = DATA['profile_url']
IMAGES = json.loads((ROOT/'data/images.json').read_text())
ARROW = '<span class="arrow" aria-hidden="true">↗</span>'
pages = []

def img(name, alt, cls='', eager=False):
    size=IMAGES[name+'.webp']
    loading='loading="eager" fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<img src="assets/images/{name}.webp" alt="{escape(alt)}" width="{size[0]}" height="{size[1]}" class="{cls}" {loading} decoding="async">'

def figure(name, alt, caption, cls='', eager=False):
    return f'<figure class="{cls}"><a class="zoom-link" href="assets/images/{name}.webp" data-image data-caption="{escape(caption)}" aria-label="Enlarge image: {escape(alt)}">{img(name,alt,eager=eager)}</a><figcaption class="caption">{caption}</figcaption></figure>'

def link(url, label, cls='text-link'):
    return f'<a class="{cls}" href="{escape(url)}">{label}{ARROW}</a>'

def eyebrow(text): return f'<span class="eyebrow">{text}</span>'

def head(kicker,title,lead='',actions=''):
    return f'<div class="page-head">{eyebrow(kicker)}<h1>{title}</h1>{f"<p class=lead>{lead}</p>" if lead else ""}{actions}</div>'

def write_page(file,title,description,body,active='home'):
    nav=''
    for key,label,url in [('home','Home','index.html'),('research','Research','research.html'),('publications','Publications','publications.html'),('practice','Practice','practice.html'),('about','About','about.html')]:
        nav+=f'<a href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>'
    canonical='https://www.xingtingwu.com/'+('' if file=='index.html' else file)
    social_image='portrait' if file in ['index.html','about.html'] else 'garden-map'
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} · Xingting Wu</title><meta name="description" content="{escape(description)}">
<meta name="theme-color" content="#f7f5ef"><link rel="canonical" href="{canonical}">
<meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} · Xingting Wu"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://www.xingtingwu.com/assets/images/{social_image}.webp">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script>
<noscript><style>@media(max-width:760px){{.site-header{{position:static}}.header-inner{{height:auto;display:block;padding-block:20px}}.nav{{display:flex;position:static;padding:15px 0 0;flex-direction:row;flex-wrap:wrap;border:0;gap:15px}}.nav .contact-link{{margin:0}}}}</style></noscript>
</head><body><a class="skip" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Xingting Wu, home"><span class="brand-mark" aria-hidden="true">xw</span><span>Xingting Wu <span class="chinese" lang="zh">武星廷</span></span></a>
<button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" hidden>Menu <span aria-hidden="true">☰</span></button><nav class="nav" id="main-nav" aria-label="Main navigation">{nav}<a class="contact-link" href="about.html#contact">Get in touch ↗</a></nav></div></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="wrap"><div class="footer-main"><div>{eyebrow('A conversation starts somewhere')}<h2>Let’s make connections.</h2><p>Research, design, and everyday life. Based in Melbourne.</p></div><div class="footer-links"><a href="mailto:xingtingwu@swin.edu.au">Email ↗</a><a href="{SCHOLAR}">Google Scholar ↗</a><a href="https://xhslink.com/m/4sUuQcr9thK">Artwork ↗</a></div></div><div class="footer-bottom"><span>© 2026 Xingting Wu · <span lang="zh">武星廷</span></span><span>Design researcher &amp; illustrator · Swinburne University of Technology</span><a href="privacy.html">Photography &amp; privacy</a></div></div></footer>
<dialog class="lightbox" id="image-dialog" aria-label="Enlarged project photograph"><button type="button" aria-label="Close image">✕</button><img alt=""><p></p></dialog>
</body></html>'''
    (ROOT/file).write_text(html,encoding='utf-8')
    if file!='404.html': pages.append(canonical)

PROJECTS=[
 dict(id='crafting',title='Making together',year='2024',stage='01 / Crafting',image='nativity-finished',alt='Completed Nativity display with hand-decorated figures in a raised garden bed',desc='Shared crafting, brought together in an outdoor Nativity display.'),
 dict(id='gardening',title='Our Garden',year='2025',stage='02 / Gardening',image='garden-together',alt='People holding and planting a flowering plant together at a raised garden bed',desc='Exploring plants, care, and the rhythms of everyday participation.'),
 dict(id='outdoor-discovery',title='Following curiosity',year='2025',stage='03 / Outdoor discovery',image='garden-map',alt='A hand-drawn garden map with photographs of places in the garden',desc='Maps, nature cards, and birdsong as invitations to notice and share.',material=True)
]

HOME_PROJECTS=PROJECTS[:2]+[
 dict(id='outdoor-stories',title='Our Outdoor Stories',year='2026–ongoing',stage='03 / Plants & stories',image='labelled-flowers',alt='A glass bottle of protea flowers with handwritten plant-story tags',desc='From a chosen flower to a personal memory and a shared display.',specimen=True)
]

def project_grid(projects=PROJECTS):
    cards=''
    for p in projects:
        photo_class='specimen' if p.get('specimen') else 'contain' if p.get('material') else ''
        cards+=f'''<a class="project-link" href="{p['id']}.html"><div class="image-wrap">{img(p['image'],p['alt'],photo_class)}</div><div class="project-number"><span>{p['stage']}</span><span>{p['year']}</span></div><h3>{p['title']}{ARROW}</h3><p>{p['desc']}</p></a>'''
    return '<div class="project-grid">'+cards+'</div>'

def selected():
    rows=''
    for id in ['Tyk-4Ss8FVUC','0EnyYjriUFMC','roLk4NBRz8UC']:
        p=next(x for x in PAPERS if x['id']==id)
        rows+=f'<a class="selected-paper" href="publications.html#pub-{id}"><span class="year">{p["year"]} / {"01" if id=="Tyk-4Ss8FVUC" else "02" if id=="0EnyYjriUFMC" else "03"}</span><div><h3>{escape(p["title"])}</h3><p>{escape(p["venue"])}</p></div>{ARROW}</a>'
    return '<div class="selected-list">'+rows+'</div>'

home=f'''<div class="wrap"><section class="profile-hero fade-in" aria-labelledby="profile-title">
<figure class="profile-photo">{img('portrait','Xingting Wu making a colourful artwork',eager=True)}<figcaption><span>Researcher. Designer. Illustrator.</span><span>Melbourne, Australia</span></figcaption></figure>
<div class="profile-intro"><span class="eyebrow"><span class="dot"></span>Hello, I’m</span><h1 id="profile-title">Xingting Wu<span class="profile-name-zh" lang="zh">武星廷</span></h1><p class="profile-role">PhD candidate in Design</p><p class="profile-affiliation">Swinburne University of Technology · Melbourne</p><div class="profile-bio"><p>I’m a design researcher and illustrator working at the intersection of human–computer interaction, participatory design, and everyday life.</p><p>My PhD explores outdoor engagement in residential aged care. I work with older adults and care staff through crafting, gardening, and nature discovery to understand how design can support meaningful participation.</p><p>My wider research looks at human–AI interaction, creative practice, and learning across generations.</p></div><div class="profile-links">{link(SCHOLAR,'Google Scholar','button')}{link('mailto:xingtingwu@swin.edu.au','Email')}{link('about.html','More about me')}</div></div>
</section>
<section class="section home-projects" id="projects"><div class="phd-intro"><div>{eyebrow('01 / Selected projects')}<h2>Making, growing,<br><em>sharing.</em></h2></div><div><p>My doctoral research follows the connections between creative activities, outdoor places, and everyday care. These projects bring that work into view.</p><div class="actions">{link('research.html','The full research journey')}</div></div></div>{project_grid(HOME_PROJECTS)}</section>
<section class="section home-publications"><div class="section-head"><div>{eyebrow('02 / Selected publications')}<h2>Recent writing.</h2></div>{link('publications.html','All publications (18)')}</div>{selected()}</section></div>
<section class="feature-band"><div class="wrap feature"><div class="feature-photos">{img('sharing-plants','A group sharing flowers and talking around a table')}{img('plant-preference','A handwritten tag recording a preference for Grevillea flowers','inset')}</div><div>{eyebrow('03 / Currently in the field · 2026')}<h2>A plant. A memory.<br><em>A conversation.</em></h2><p>In Our Outdoor Stories, garden walks continue indoors through chosen plants, handwritten labels, and a shared display. I’m exploring how these small contributions can be revisited between activities.</p><div class="mini-meta"><span>Walking</span><span>Plant choices</span><span>Shared stories</span></div><div class="actions">{link('outdoor-stories.html','Inside Our Outdoor Stories','button')}</div></div></div></section>
<div class="wrap"><section class="practice-teaser home-practice" id="design-practice"><div>{eyebrow('04 / Design practice')}<h2>From a drawing<br>to <em>making together.</em></h2><p>This Nativity garden concept brings handmade figures, plants, light, and sound into one shared setting. The work continues through prototyping at ProtoLAB and preparing materials for the workshops.</p><div class="actions">{link('practice.html','Behind the materials')}</div></div>{figure('garden-concept','Hand-drawn Nativity garden-bed concept with crafted figures, plants, lighting, sensors and a music speaker','Nativity garden-bed concept, 2024.')}</section><section class="section updates"><div>{eyebrow('Notes & updates')}<h2>Currently.</h2></div><div><div class="update-row"><time datetime="2026-09">Sep 2026</time><p>Developing <a href="outdoor-stories.html">Our Outdoor Stories</a>: connecting garden walks, plant choices, and a shared display.</p></div><div class="update-row"><time datetime="2026-04">Apr 2026</time><p>Bringing together crafting, gardening, and outdoor discovery in my doctoral research.</p></div><div class="update-row"><time datetime="2026">2026</time><p>New work on <a href="publications.html#pub-0EnyYjriUFMC">intergenerational GenAI learning</a> and <a href="publications.html#pub-roLk4NBRz8UC">creative identity in human–AI co-creation</a>.</p></div></div></section></div>'''
write_page('index.html','Design researcher & illustrator','Meet Xingting Wu, a PhD candidate at Swinburne University of Technology researching participatory design, older adults, outdoor engagement and human–AI interaction.',home)

research=f'''<div class="wrap">{head('Research / PhD in Design','Designing meaningful connections<br>with the <em>outdoors.</em>','My doctoral research explores how design can support older adults’ engagement with outdoor places in residential aged care. Making, gardening, and nature discovery offer different ways to take part.')}<div class="research-question"><span class="eyebrow">The doctoral project<br><br>Enhancing Outdoor Engagement for Older Adults in Residential Aged Care</span><p>How can design support meaningful outdoor engagement within the realities of everyday care?</p></div><section class="section"><div class="section-head"><div>{eyebrow('A developing research journey')}<h2>From making to noticing.</h2></div></div><div class="timeline"><a href="crafting.html"><span>2024 · Study 1</span><h3>Making</h3><p>Connecting shared crafts with outdoor spaces.</p></a><a href="gardening.html"><span>2025 · Study 2</span><h3>Growing</h3><p>Exploring plant care and participation over time.</p></a><a href="outdoor-discovery.html"><span>2025 · Study 3</span><h3>Discovering</h3><p>Following curiosity through maps, cards, and sound.</p></a><a href="outdoor-stories.html"><span>2026 · Ongoing exploration</span><h3>Sharing</h3><p>Connecting walks, personal choices, and shared stories.</p></a></div><p class="note">These projects inform one another. They offer different ways of participating; they are not a sequence that every participant follows.</p>{project_grid()}<div class="actions">{link('outdoor-stories.html','Explore the ongoing Our Outdoor Stories project')}</div></section><section class="section" style="padding-top:0"><div class="section-head"><div>{eyebrow('How I work')}<h2>Design grows through<br><em>working together.</em></h2></div></div><div class="method-grid"><div class="method"><span class="number">01</span><h3>Start with everyday life</h3><p>Observe existing activities and listen to residents and staff. Attend to familiar routines, preferences, and the practical conditions of taking part.</p></div><div class="method"><span class="number">02</span><h3>Make, try, and adjust</h3><p>Develop tangible materials and try them together. Reconsider complexity, visibility, handling, and the kinds of contribution each activity makes possible.</p></div><div class="method"><span class="number">03</span><h3>Reflect across encounters</h3><p>Bring field observations, conversations, photographs, and reflective memos into qualitative analysis, tracing what changes and what remains difficult.</p></div></div></section><div class="research-other"><div><h2>Questions I keep<br>coming back to.</h2><p>How can an activity welcome different ways of participating? What remains after a session ends? How do materials, staff collaboration, and daily routines shape what can continue?</p></div><div><h3>Beyond the doctoral project</h3><p>My wider work considers human–AI co-creation, intergenerational technology learning, design education, and technology adoption. The Publications page brings these strands together.</p><div class="actions">{link('publications.html','Browse the wider research')}</div></div></div><p class="note">PhD in Design · Swinburne University of Technology · Supervisors: Prof. Sonja Pedell, Prof. Leon Sterling, and Dr. Diego Muñoz.</p></div>'''
write_page('research.html','Research','Doctoral research on enhancing outdoor engagement for older adults in residential aged care, through crafting, gardening and nature discovery.',research,'research')

def author_markup(text):
    return re.sub(r'(?<![\w-])(Xingting Wu|X Wu|武星廷)(?![\w-])',r'<strong>\1</strong>',escape(text))

def publication(p):
    actions=link(p['scholar_url'],'Google Scholar')
    if p.get('paper_url'): actions=link(p['paper_url'],p.get('paper_label','Read paper'))+actions
    return f'''<article class="publication" id="pub-{p['id']}" data-year="{p['year']}" data-type="{p['type']}"><div class="pub-type">{escape(p['label'])}</div><h3><a href="{escape(p.get('paper_url') or p['scholar_url'])}">{escape(p['title'])}</a></h3><p class="pub-authors">{author_markup(p['authors'])}</p><p class="pub-venue">{escape(p['venue'])} · {p['year']}</p><div class="pub-actions">{actions}</div></article>'''

pubs=f'''<div class="wrap">{head('Writing & scholarship','Publications.','Work on older adults, participatory design, human–AI interaction, and design education.', '<div class="actions">'+link(SCHOLAR,'View on Google Scholar')+'</div>')}<form id="publication-filters" class="filters" hidden role="search" aria-label="Filter publications"><div class="field"><label for="publication-search">Search publications</label><input id="publication-search" name="search" type="search" placeholder="Try older adults, co-creation, or an author…" autocomplete="off"></div><div class="field"><label for="publication-type">Publication type</label><select id="publication-type" name="type"><option value="">All types</option><option value="journal">Journal articles</option><option value="conference">Conference contributions</option><option value="preprint">Preprints</option></select></div><div class="field"><label for="publication-year">Year</label><select id="publication-year" name="year"><option value="">All years</option>{''.join(f'<option>{y}</option>' for y in [2026,2025,2022,2021])}</select></div><button class="reset" type="reset">Clear filters ↺</button></form><p class="result-count" id="publication-count" role="status" aria-live="polite">18 publications · Updated 20 September 2026</p><div id="no-publications" class="empty-state" hidden><h2>No matching publications.</h2><p>Try a broader search, another year, or clear the filters.</p></div>'''
for year in [2026,2025,2022,2021]:
    pubs+=f'<section class="pub-year" aria-labelledby="year-{year}"><h2 id="year-{year}">{year}</h2><div>'+''.join(publication(p) for p in PAPERS if p['year']==year)+'</div></section>'
pubs+='<p class="note">List based on my Google Scholar profile, updated 20 September 2026. Preprints and conference contributions are labelled separately from journal articles.</p></div>'
write_page('publications.html','Publications','Publications by Xingting Wu: journal articles, conference contributions and preprints, with links to Google Scholar and public paper versions.',pubs,'publications')

def project_page(file,title,kicker,lead,year,focus,cover,alt,caption,sections,next_project,material=False):
    toc='<aside class="toc" aria-label="On this page">'+eyebrow('In this project')+''.join(f'<a href="#{id}">{heading}</a>' for id,heading,content in sections)+'</aside>'
    content=''.join(f'<section id="{id}"><h2>{heading}</h2>{html}</section>' for id,heading,html in sections)
    body=f'''<div class="wrap"><div class="page-head"><a class="bread" href="research.html">← All research</a>{eyebrow(kicker)}<h1>{title}</h1><p class="lead">{lead}</p><dl class="project-meta"><div><dt>When</dt><dd>{year}</dd></div><div><dt>Context</dt><dd>Residential aged care</dd></div><div><dt>Focus</dt><dd>{focus}</dd></div></dl></div>{figure(cover,alt,caption,'project-cover'+(' material' if material else ''),True)}<div class="article-layout">{toc}<div class="prose">{content}</div></div><a class="next-project" href="{next_project[0]}"><div>{eyebrow('Continue exploring')}<h2>{next_project[1]}</h2></div>{ARROW}</a></div>'''
    write_page(file,title.replace('<br>',' ').replace('<em>','').replace('</em>',''),lead,body,'research')

def learning(title,text): return f'<div class="learning">{eyebrow(title)}<p>{text}</p></div>'

project_page('outdoor-stories.html','Our Outdoor<br><em>Stories.</em>','Ongoing design exploration / 2026','Connecting garden walks, plant choices, and shared stories across indoor and outdoor spaces.','2026 · Ongoing','Walking · Storytelling · Shared displays','stories-wall','Our Outdoor Stories display with a route map, plants, photographs and handwritten cards','The shared display brings together maps, plants, photographs, and handwritten contributions, September 2026.',[
('starting-point','Begin with a familiar walk.','<p>This project starts with an activity that already exists: morning walks. I am exploring how simple materials can help connect what people notice outdoors with conversations and contributions indoors.</p><p>The design includes route maps, plant photographs, story invitations, and a shared display. Working with care staff means attending to how walks are organised, who wants to join, and what can fit into everyday routines.</p>'+figure('walking','A person on a garden path using a walker','A garden walk during Our Outdoor Stories, September 2026.','photo-wide')),
('many-ways','More than one way to join.','<p>Participation can include walking, looking at a photograph, handling a plant, talking, drawing, or asking someone to write down a thought. Indoor conversations also create an opening for people who have not joined a walk.</p>'+figure('sharing-plants','Shared conversation with plants and printed materials','Plants and printed materials around the table provide several starting points for conversation.','photo-wide')+learning('A practical design question','Holding a card can compete with keeping both hands on a walker. Observations like this are shaping questions about carrying materials, pausing along a route, and support from a companion.')),
('plant-choices','A preference leaves a trace.','<p>Plant choices offer a concrete place to start. A colour, a texture, or a flower’s shape can become something to notice and describe. Handwritten labels keep a record of these preferences.</p><div class="image-pair">'+figure('plants-on-table','Fresh plant materials arranged on a table','Real flowers and foliage used in the activity.')+figure('plant-preference','Grevillea preference label recording a plant choice','A recorded preference for petal shape and colour. The tag records what caught someone’s attention.','')+'</div><p class="note">The labels record small, specific observations, while the story invitations leave room for a longer contribution.</p>'),
('plant-stories','A flower can hold a story.','<p>Handwritten tags connect chosen plants with observations, preferences, and memories. Placed around a glass bottle, these contributions stay close to the flower that prompted them.</p>'+figure('labelled-flowers','Protea flowers in a glass bottle with handwritten tags','Flowers and handwritten contributions in the Our Outdoor Stories display, September 2026.','portrait-figure')),
('continuity','What stays after the session?','<p>The display brings a route map, plant information, contributions, and fresh flowers into a shared indoor space. Story invitations and flower-care materials are part of the ongoing exploration of what might carry an activity beyond a single meeting.</p>'+figure('care-diary','A blank flower care diary with spaces to record watering','A flower-care diary template, designed to invite care between activities.')+learning('Questions still in progress','What draws someone back to the display? Who adds to it or looks after the flowers? How can the activity continue when the researcher is not there?')+'<p class="note">This project is ongoing. The photographs document activities and materials, while longer-term use and outcomes remain research questions.</p>')
],('crafting.html','Making together'))

project_page('crafting.html','Making<br><em>together.</em>','PhD research / Study 1','Exploring how shared crafting can connect indoor activities with outdoor places, and make personal contributions visible.','2024','Participatory making · Material adaptation · Garden displays','nativity-finished','A completed outdoor Nativity display with hand-decorated figures and plants','The completed Nativity display brings the figures made during the workshops into a shared outdoor setting, December 2024.',[
('invitation','An invitation to make.','<p>Crafting offered a way to begin with familiar interests and tangible materials. Residents and staff took part in making nature-inspired decorations and figures, with the possibility of displaying contributions outdoors.</p><p>The research explored how digital fabrication tools, including a Cricut and laser cutting, could help prepare materials for shared making. The design work involved both preparing the activity and adapting it to the people taking part.</p>'+figure('craft-process','Illustrated sequence of technology demonstrations, shared making and outdoor connections','An illustrated overview of crafting activities and their connections with the garden.')),
('preparation','Before the workshop.','<p>I prepared the making activities by testing paper shapes with the Cricut and developing wooden parts for laser cutting. At the university makerspace, the designs moved from Adobe Illustrator files to physical pieces that could be handled, assembled, and decorated.</p>'+figure('protolab-making','Xingting Wu working at a laser cutter in Swinburne ProtoLAB','Preparing materials at Swinburne ProtoLAB. Still from an original preparation video, 2024.','photo-wide')+'<p>I also recorded the laser-cutting process and shared it during the workshops, so participants could see how the materials were made.</p>'+figure('nativity-cut-layout','Cutting layout showing Nativity figures, animals, slots and bases','A Nativity cutting layout with figure outlines, slots, and separate bases.')+'<div class="actions">'+link('practice.html#making-process','Explore the making process')+'</div>'),
('iteration','Make the material easier to enter.','<p>Early Nativity models involved multiple interlocking pieces. Handling and fitting these parts could make assembly difficult. Staff suggestions and observations during sessions informed a simpler approach.</p>'+figure('craft-materials','Participants assembling wooden sheep models at a table','Early assembly work illustrates the handling demands of a multipart model.')+learning('From observation to a design change','The sheep was simplified to a body shape and two leg pieces. Other figures used an outline and a base. This shifted attention toward decorating and personalising the objects.')+'<p>Reducing assembly demands did not mean deciding the decoration for participants. It created more room for different choices of colour, texture, and character.</p>'),
('outdoors','Let contributions travel outdoors.','<p>Crafted objects became part of garden-bed displays. The outdoor setting offered a place to encounter the results of earlier making and to share them with other people.</p><p>This raised questions about visibility and recognition: where should a contribution be placed, how can someone see it, and what makes a display worth returning to?</p>'+learning('Design reflection','The relationship between making an object and later encountering it matters. Materials, placement, and staff collaboration all shape that connection.')),
('next','What this opened up.','<p>The crafting study drew attention to material accessibility, staff collaboration, and the value of keeping contributions visible. The gardening study then explored participation through living plants, care, and change over time.</p><div class="actions">'+link('gardening.html','Continue to Our Garden')+'</div>')
],('gardening.html','Our Garden'))

project_page('gardening.html','Our<br><em>Garden.</em>','PhD research / Study 2','Exploring how plants, shared care, and everyday relationships shape outdoor engagement in residential aged care.','April–October 2025','Gardening · Sensory encounters · Indoor–outdoor connections','garden-together','People working together with soil and plants at a raised garden bed','Planting together at a raised garden bed during the gardening study.',[
('planting','Working with living things.','<p>Gardening brings a different rhythm to participation. Plants grow, change, and need care between organised activities. This study followed gardening activities over time, attending to practical work, sensory encounters, and the relationships formed around plants.</p><p>Shared activities included choosing plants, planting, and discussing what people noticed. Weather, space, and staff availability were part of the conditions that shaped participation.</p>'),
('inside-outside','The garden reaches indoors.','<p>Outdoor engagement did not always mean being physically outside. Photographs and plants could bring the garden into indoor conversations. Plants adopted into personal spaces also became part of the relationship between individual care and a shared garden.</p><p>The study followed the movement of plants between personal spaces and communal areas, and explored how photographs might support remembering and talking about garden activities.</p>'+learning('A connection across places','The design question is not simply how to increase time outdoors. It also concerns what can make the garden present, approachable, and meaningful within daily life.')),
('technology','Technology within the activity.','<p>Photographs and a plant-character chatbot were explored as ways to support looking back and conversation. These experiments also exposed limits: responses depended on the situation, the person, and the support available.</p><p>The research treats technology as something to examine within real activities. A device or a conversational response is not, by itself, evidence of meaningful participation.</p>'),
('learning','Care is part of the design.','<p>Participation developed within everyday arrangements: where a plant could be kept, who could help, and how an activity fitted the day. These details were central to understanding what could continue.</p>'+learning('Design reflection','A garden activity includes the work before and after a session. Designing for continuity means attending to ongoing care, staff collaboration, and opportunities to revisit a contribution.')+'<p>The next study explored curiosity about the wider outdoor environment through maps, nature cards, and birdsong.</p>')
],('outdoor-discovery.html','Following curiosity'))

project_page('outdoor-discovery.html','Following<br><em>curiosity.</em>','PhD research / Study 3','Using maps, nature cards, and birdsong to invite noticing, recognition, imagination, and shared conversation.','November–December 2025','Nature discovery · Visual materials · Sound','garden-map','Hand-drawn garden map with photographs of garden areas','The garden map pairs an illustrated layout with photographs of familiar places.',[
('noticing','Start with what catches attention.','<p>A bird call, a familiar plant, or an unexpected detail can open a conversation. This study explored outdoor ecological discovery through materials that residents could look at, listen to, choose, and discuss.</p><p>An activity-preference booklet helped invite choices about what to explore. The materials offered different entry points, rather than expecting everyone to take part in the same way.</p>'),
('materials','A small collection of invitations.','<p>The toolkit brought together a hand-drawn map, plant and animal cards, clue and fact cards, and birdsong. Photographs supported recognition, while questions and sound invited people to contribute their own knowledge and associations.</p>'+figure('nature-cards','A collection of plant, animal, clue and fact cards','Nature cards use distinct categories for identification, clues, and ecological facts.')+'<p>Maps were useful for some conversations about places, while understanding and locating oneself on a map varied. The design needed to accommodate this difference.</p>'),
('curiosity','Different forms of curiosity.','<p>The analysis considered observational, identificatory, imaginative, and connective forms of curiosity. Some exchanges began with looking closely or naming a bird. Others moved toward possibilities, associations, or a remembered place.</p>'+learning('A material can outlast an activity','Some residents chose to keep bird images. This points to the importance of what a person can take away, retain, or revisit after the group activity finishes.')),
('design','Keep the invitation accessible.','<p>Visibility, pace, and opportunities to respond shaped participation. In group activities, a small card or a quickly spoken clue could be difficult to follow.</p><p>These observations inform the ongoing Our Outdoor Stories exploration, which connects walking, plant choices, and materials that remain visible in a shared space.</p><div class="actions">'+link('outdoor-stories.html','See the ongoing exploration')+'</div>')
],('outdoor-stories.html','Our Outdoor Stories'),True)

practice_items=[
('garden-map','Garden maps','Making a place discussable','Illustrated maps bring places into a conversation. Pairing drawings with photographs offers several ways to recognise a garden area and talk about where to go.','outdoor-discovery.html','Explore Outdoor Discovery'),
('plant-cards','Plant photographs','Something to notice, hold, and choose','Photographic cards bring flowers and foliage into both outdoor walks and indoor conversations. Their role is to invite attention and preferences.','outdoor-stories.html','Explore Our Outdoor Stories'),
('garden-concept','Craft & fabrication','From a drawing to a shared setting','Garden concepts connect crafted objects with their eventual setting. Materials and assembly are adjusted through collaboration and observation.','crafting.html','Explore Making Together'),
('nature-cards','A collection of prompts','Room for curiosity','Identification, clue, and fact cards offer different ways into a topic, from recognising a plant to sharing something unexpected.','outdoor-discovery.html','Explore the research'),
('story-invitation','Story invitations','Leave room for a contribution','A story invitation gives a contribution somewhere to go. The material can support a thought, a drawing, or words recorded with assistance.','outdoor-stories.html','See the project'),
('care-diary','Between activities','Designing for what happens next','Care invitations and a flower diary explore how participation might continue between facilitated sessions. They remain part of an ongoing design inquiry.','outdoor-stories.html#continuity','Read about continuity')
]
practice=f'''<div class="wrap">{head("Design practice / Behind the materials","From the studio<br><em>to the garden.</em>","I draw, make, and test the materials I bring into research. From paper experiments to laser-cut wooden figures, preparation is part of understanding what people can hold, assemble, decorate, and share.")}
<div class="making-portraits">
{figure('protolab-making','Xingting Wu working at a laser cutter in Swinburne ProtoLAB','At the laser cutter in Swinburne ProtoLAB. Still from a preparation video, 2024.','making-lab',True)}
{figure('cricut-preparation','Xingting Wu carefully removing cut paper shapes from a green Cricut mat','Preparing and trying out paper forms with the Cricut, August 2024.','making-paper')}
</div>
<section class="section making-process" id="making-process"><div class="section-head"><div>{eyebrow('From an idea to something people can use')}<h2>How the materials<br><em>take shape.</em></h2></div><p class="process-context">A look inside the preparation for the 2024 crafting study.</p></div>
<ol class="making-steps">
<li>{figure('nativity-cut-layout','Digital cutting layout for Nativity figures and their bases','A Nativity cutting layout.','technical-drawing')}{eyebrow('01 / Draw & prepare')}<h3>Work out the parts.</h3><p>I prepare digital outlines for figures, animals, slots, and bases. The drawing connects the visual idea with practical decisions about how an object will be made and put together.</p></li>
<li>{figure('laser-cutting','A laser cutter producing wooden sheep components','Wooden parts during laser cutting. Video still, 2024.')}{eyebrow('02 / Make & prototype')}<h3>Take it into the workshop.</h3><p>At ProtoLAB, cutting turns a file into physical pieces. Alongside these wooden prototypes, I try paper shapes with the Cricut and prepare materials for the group activities.</p></li>
<li>{figure('wooden-prototype','An early wooden sheep model laid out as separate interlocking parts','The separate parts of an early sheep prototype. Video still, 2024.')}{eyebrow('03 / Handle & test')}<h3>See what assembly asks of us.</h3><p>The early sheep used many interlocking pieces. Handling and trying the model helped reveal the demands of fitting, holding, and connecting those parts.</p></li>
</ol>
<div class="making-reflection"><h3>Then the activity<br>changes the design.</h3><div><p>Workshop observations and staff feedback informed a simpler sheep: a body shape and two leg pieces. Other figures used an outline and a base, leaving more room for decorating and personal choices.</p><div class="actions">{link('crafting.html#iteration','See how the design changed')}</div></div></div></section>
<section class="material-library" id="materials"><div class="section-head"><div>{eyebrow('Materials from the research')}<h2>Made for a<br><em>shared activity.</em></h2></div></div><div class="practice-grid">'''
for name,kicker,title,text,url,label in practice_items:
    practice+=f'<article class="practice-item">{figure(name,title,"Design material from the research practice.")}{eyebrow(kicker)}<h2>{title}</h2><p>{text}</p><div class="actions">{link(url,label)}</div></article>'
practice+=f'</div></section><section class="section research-other" id="illustration"><div><h2>Beyond the fieldwork.</h2></div><div><p>I also draw, illustrate, and teach art. For more of my illustration practice and visual explorations, visit my artwork collection.</p><div class="actions">{link("https://xhslink.com/m/4sUuQcr9thK","Artwork on Xiaohongshu")}{link("about.html#contact","Discuss a collaboration")}</div></div></section></div>'
write_page('practice.html','Design practice','Behind Xingting Wu’s design research: material preparation, Cricut experiments, ProtoLAB fabrication, illustrated maps and activity materials.',practice,'practice')

about=f'''<div class="wrap"><section class="about-layout"><figure class="about-portrait">{img('portrait','Xingting Wu working on an artwork',eager=True)}<figcaption class="caption">Exploring an artwork, 2023.</figcaption></figure><div class="about-copy">{eyebrow('A little about me')}<h1>Xingting Wu.<br><span lang="zh" style="font-size:.53em;letter-spacing:.08em">武星廷</span></h1><p class="lead">Designer, researcher,<br>and illustrator.</p><p>I’m a PhD candidate in the School of Design and Architecture at Swinburne University of Technology in Melbourne.</p><p>My research focuses on participatory design with older adults in residential aged care. Through crafting, gardening, and outdoor discovery, I explore how design can support meaningful connections with places and with other people.</p><p>Alongside my doctoral work, I study human–AI interaction, creative identity, intergenerational learning, and design education. Illustration is both a personal practice and a way of making ideas tangible within research.</p><div class="actions">{link('research.html','My research')}{link(SCHOLAR,'Google Scholar')}</div></div></section><section class="section research-other"><div><h2>Learning &<br><em>collaboration.</em></h2><p>My doctoral research is supervised by Prof. Sonja Pedell, Prof. Leon Sterling, and Dr. Diego Muñoz, and supported by an ARC full scholarship.</p></div><div class="education"><div class="education-row"><span>2024–present</span><div><strong>PhD in Design</strong><br>Swinburne University of Technology<br>Melbourne, Australia</div></div><div class="education-row"><span>2019–2022</span><div><strong>Master of Fine Arts</strong><br>School of Design, Hunan University<br>Changsha, China</div></div><div class="education-row"><span>2015–2019</span><div><strong>Bachelor’s degree</strong><br>Art Academy, Northeast Agricultural University<br>Harbin, China</div></div></div></section><section class="research-other"><div><h2>Away from the desk.</h2></div><div><p>I enjoy board games, especially Splendor Duel, and exploring new ways of drawing and making. I volunteer through the Aged Care Volunteer Visitors Scheme in Melbourne.</p><p>I share <a href="https://xhslink.com/m/1MBa8EERfhz">academic reading notes</a> and <a href="https://xhslink.com/m/4sUuQcr9thK">artwork</a> on Xiaohongshu, and run mobile drawing lessons in Melbourne.</p></div></section><section class="contact-panel" id="contact">{eyebrow('Get in touch')}<h2>There’s room for a conversation.</h2><p>For research collaborations, peer review invitations, illustration commissions, or drawing lesson enquiries.</p><a class="email" href="mailto:xingtingwu@swin.edu.au">xingtingwu@swin.edu.au ↗</a><p class="note">School of Design and Architecture<br>Swinburne University of Technology · Melbourne, Australia</p></section></div>'''
write_page('about.html','About & contact','About Xingting Wu, PhD candidate, design researcher and illustrator at Swinburne University of Technology in Melbourne.',about,'about')

privacy=f'''<div class="wrap">{head('Care in representation','Photography & privacy.')}<div class="privacy-text"><p>The research photographs on this website show materials, activities, and shared settings. Photographs are shown alongside descriptions of the activity or material.</p><h2>Respecting personal contributions</h2><p>Captions focus on activities and design materials. Personal contributions remain part of the context in which they were shared; photographs are not used to infer a person’s abilities or health.</p><h2>Questions about a photograph</h2><p>If you appear in a photograph, or would like to discuss, correct, or remove an image, please contact <a href="mailto:xingtingwu@swin.edu.au">xingtingwu@swin.edu.au</a>.</p></div></div>'''
write_page('privacy.html','Photography & privacy','How research photographs and participant contributions are represented on this website.',privacy,'')
